import { useLocalSearchParams } from 'expo-router';
import { useEffect, useState } from 'react';
import { Alert, Button, StyleSheet, Text, TextInput, View } from 'react-native';
import { fetchStockMovements, fetchStocks, recordStockMovement } from '../../../services/api';
import { useTheme } from '../../../hooks/useTheme';
import { Gap } from '../../../constants/theme';
export default function InventoryDetailScreen() { const colors = useTheme(); const { id } = useLocalSearchParams<{ id: string }>(); const [stock, setStock] = useState<any>(); const [quantity, setQuantity] = useState(''); const [reason, setReason] = useState(''); const [movements, setMovements] = useState<any[]>([]); const load = async () => { const all = await fetchStocks(); setStock(all.find((x) => x.id === id)); setMovements(await fetchStockMovements(String(id))); }; useEffect(() => { void load(); }, [id]); const record = async (type: 'usage') => { try { await recordStockMovement(String(id), { type, quantity: Number(quantity), reason }); setQuantity(''); setReason(''); await load(); Alert.alert('Saved', 'Material out recorded.'); } catch (e: any) { Alert.alert('Unable to save', e?.response?.data?.error || e?.message || 'Try again.'); } }; if (!stock) return <View style={styles.center}><Text style={{ color: colors.textMuted }}>Loading inventory detail…</Text></View>; return <View style={[styles.page, { backgroundColor: colors.background }]}><Text style={[styles.title, { color: colors.text }]}>{stock.materialName || 'Material'}</Text><Text style={{ color: colors.textMuted }}>Available: {stock.remainingQuantity ?? 0} {stock.unit || ''}</Text><TextInput inputAccessoryViewID="trucksphere-keyboard-done" style={[styles.input, { color: colors.text, borderColor: colors.border }]} placeholder="Quantity" placeholderTextColor={colors.textMuted} keyboardType="decimal-pad" value={quantity} onChangeText={setQuantity} /><TextInput inputAccessoryViewID="trucksphere-keyboard-done" style={[styles.input, { color: colors.text, borderColor: colors.border }]} placeholder="Reason / reference" placeholderTextColor={colors.textMuted} value={reason} onChangeText={setReason} /><View style={styles.actions}><Button title="Record material out" color="#DC2626" onPress={() => record('usage')} /></View><Text style={[styles.heading, { color: colors.text }]}>Movement history</Text>{movements.length ? movements.map((m) => <View key={m.id} style={{ marginBottom: 12, paddingBottom: 12, borderBottomWidth: 1, borderBottomColor: colors.border }}><Text style={{ color: colors.text, fontWeight: '700' }}>{m.type === 'receipt' ? 'Material in' : 'Material out'} · {m.quantity ?? 0} {m.unit || ''}</Text><Text style={{ color: colors.textMuted }}>{m.reason || '—'}</Text><Text style={{ color: colors.textMuted }}>{m.createdAt ? new Date(m.createdAt).toLocaleString('en-KE', { timeZone: 'Africa/Nairobi' }) : '—'}{m.actorName ? ` · ${m.actorName}` : ''}</Text></View>) : <Text style={{ color: colors.textMuted }}>No movements recorded yet.</Text>}</View>; }
const styles = StyleSheet.create({ page: { flex: 1, padding: 20 }, center: { flex: 1, alignItems: 'center', justifyContent: 'center' }, title: { fontSize: 25, fontWeight: '800', marginBottom: 8 }, input: { borderWidth: 1, borderRadius: 8, padding: 12, marginTop: 12 }, actions: { gap: Gap, marginTop: 14 }, heading: { fontSize: 18, fontWeight: '800', marginTop: 26, marginBottom: 12 } });
