export function isJobFueled(job: any, records: any[], completedJobIds: string[] = []): boolean {
  const ids = [job.id, job.jobId].filter(Boolean);
  return ids.some((id) => completedJobIds.includes(id)) || records.some((record) =>
    [record.deliveryOrderId, record.jobId].some((id) => id && ids.includes(id)),
  );
}
