import { SearchField } from '../../components/EnterpriseUI';
import { useState, useEffect } from 'react';
import { FlatList, StyleSheet, Text, TextInput, TouchableOpacity, View } from 'react-native';
import { Ionicons } from '@expo/vector-icons';
import { router } from 'expo-router';
import { Gap, Radius, Spacing } from '../../constants/theme';
import { useTheme } from '../../hooks/useTheme';
import { fetchPurchaseOrders } from '../../services/api';

export default function ActiveOrdersScreen() {
  const colors = useTheme();
  const [search, setSearch] = useState('');
  const [orders, setOrders] = useState<any[]>([]);

  useEffect(() => {
    fetchPurchaseOrders().then(data => {
      setOrders(data);
    }).catch(() => {});
  }, []);

  const filtered = orders.filter((o) => o.status !== 'completed').filter((o) =>
    (o.id || o.poNumber || '').toLowerCase().includes((search || '').toLowerCase())
  );

  return (
    <View style={[styles.container, { backgroundColor: colors.background }]}>
      <SearchField title="Active Orders" icon="receipt-outline" value={search} onChangeText={setSearch} placeholder="Search orders..." />
      <FlatList
        data={filtered}
        keyExtractor={(o) => o.id || o.poNumber}
        contentContainerStyle={{ padding: 16 }}
        renderItem={({ item }) => (
          <TouchableOpacity
            style={[styles.card, { backgroundColor: colors.surface, borderColor: colors.border }]}
            onPress={() => router.push({ pathname: '/screens/purchase-order', params: { id: item.id || item.poNumber } })}
          >
            <View style={styles.cardHeader}>
              <Text style={[styles.id, { color: colors.accent }]}>{item.id || item.poNumber}</Text>
              <Text style={[styles.status, { color: '#D97706' }]}>{item.status.replace('_', ' ')}</Text>
            </View>
            <Text style={[styles.text, { color: colors.textSecondary }]}>
              {item.material || item.materialName} - {item.quantity}T
            </Text>
          </TouchableOpacity>
        )}
      />
    </View>
  );
}

const styles = StyleSheet.create({
  container: { flex: 1 },
  searchWrap: {
    flexDirection: 'row',
    alignItems: 'center',
    marginHorizontal: Spacing.lg, marginTop: Spacing.xs,
    borderRadius: Radius.md,
    borderWidth: 1,
    paddingHorizontal: Spacing.md,
    height: 44,
    gap: Gap,
  },
  searchInput: { flex: 1, fontSize: 14 },
  card: { borderRadius: Radius.lg, borderWidth: 1, padding: Spacing.lg, marginBottom: Spacing.xs},
  cardHeader: { flexDirection: 'row', justifyContent: 'space-between', marginBottom: Spacing.xs},
  id: { fontSize: 14, fontWeight: '700' },
  status: { fontSize: 12, fontWeight: '600' },
  text: { fontSize: 13 },
});