import { getPurchaseOrderMaterials } from './poMaterials';

const normalize = (name: string) => name.trim().toLowerCase();

function materialNames(record: any): string[] {
  return getPurchaseOrderMaterials(record)
    .map((line) => String(line.materialName || line.productName || line.name || '').trim())
    .filter(Boolean);
}

export function historyMaterialOptions(records: any[]): { id: string; name: string }[] {
  const names = new Map<string, string>();
  records.forEach((record) => materialNames(record).forEach((name) => {
    const id = normalize(name);
    if (!names.has(id)) names.set(id, name);
  }));
  return [
    { id: '', name: 'All materials' },
    ...Array.from(names, ([id, name]) => ({ id, name }))
      .sort((a, b) => a.name.localeCompare(b.name)),
  ];
}

export function matchesHistoryMaterial(record: any, material: string): boolean {
  return !material || materialNames(record).some((name) => normalize(name) === normalize(material));
}
